def palindromePartition(s, k):
    n = len(s)
    if n == k:
        return 0

    @lru_cache(None)
    def cnt(left, right):
        if left >= right:
            return 0
        return cnt(left + 1, right - 1) + (s[left] != s[right])

    @lru_cache(None)
    def dp(length, partition):
        if partition == length:
            return 0
        if partition == 1:
            return cnt(0, length - 1)
